{"file_path":"src/diff3.js","content":"/**
 * Core three-way merge logic: computing the diff of each side against the
 * base, grouping those diffs into regions, and resolving each region.
 */

/**
 * Finds the sequence of matching (baseIndex, sideIndex) pairs for the
 * longest common subsequence of `base` and `side`, comparing lines as exact
 * strings.
 *
 * When several subsequences share the maximum length, this picks the one
 * whose matches occur earliest: walking both documents from the start, a
 * match is taken whenever the current lines are equal; otherwise the walk
 * advances whichever side keeps the larger remaining-LCS length available,
 * advancing the base on a tie.
 */
function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // dp[i][j] holds the LCS length of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Describes every stretch where `side` differs from `base` as a run of base
 * lines (`baseStart` to `baseEnd`, exclusive) replaced by a run of side
 * lines (`lines`). An insertion has an empty base run; a deletion has empty
 * `lines`.
 */
function computeChanges(base, side) {
  const matches = lcsMatches(base, side)
  const changes = []
  let prevI = 0
  let prevJ = 0
  const points = matches.concat([[base.length, side.length]])
  for (const [mi, mj] of points) {
    if (prevI < mi || prevJ < mj) {
      changes.push({ baseStart: prevI, baseEnd: mi, lines: side.slice(prevJ, mj) })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  return changes
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Groups the changes from both sides into regions ordered by where they
 * start in the base. A region absorbs every following change that starts at
 * or before its current base end, extending that end to cover it.
 */
function buildRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(change => ({ ...change, source: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(change => ({ ...change, source: 'theirs' }))
  const all = mineChanges.concat(theirsChanges).sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    return a.source === b.source ? 0 : a.source === 'mine' ? -1 : 1
  })

  const regions = []
  let index = 0
  while (index < all.length) {
    const region = { baseStart: all[index].baseStart, baseEnd: all[index].baseEnd, changes: [all[index]] }
    index++
    while (index < all.length && all[index].baseStart <= region.baseEnd) {
      region.baseEnd = Math.max(region.baseEnd, all[index].baseEnd)
      region.changes.push(all[index])
      index++
    }
    regions.push(region)
  }
  return regions
}

/**
 * Reconstructs one side's version of a region: its own changes applied to
 * the region, with the base lines it left untouched filled back in between
 * and around them.
 */
function sideLines(region, base, source) {
  const changes = region.changes.filter(change => change.source === source)
  const lines = []
  let prev = region.baseStart
  for (const change of changes) {
    lines.push(...base.slice(prev, change.baseStart))
    lines.push(...change.lines)
    prev = change.baseEnd
  }
  lines.push(...base.slice(prev, region.baseEnd))
  return lines
}

/**
 * Resolves one region to a `{ kind, mine, base, theirs, lines }` record.
 * `kind` is `'mine'`, `'theirs'`, `'both'` (the sides made the same change)
 * or `'conflict'`; `lines` holds the resolved content, present only when
 * `kind` is not `'conflict'`.
 */
function resolveRegion(region, base) {
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (region.changes.length === 1) {
    const change = region.changes[0]
    const mineLines = change.source === 'mine' ? change.lines : baseLines
    const theirsLines = change.source === 'theirs' ? change.lines : baseLines
    return { kind: change.source, mine: mineLines, base: baseLines, theirs: theirsLines, lines: change.lines }
  }

  const mineLines = sideLines(region, base, 'mine')
  const theirsLines = sideLines(region, base, 'theirs')
  if (arraysEqual(mineLines, theirsLines)) {
    return { kind: 'both', mine: mineLines, base: baseLines, theirs: theirsLines, lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { kind: 'theirs', mine: mineLines, base: baseLines, theirs: theirsLines, lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { kind: 'mine', mine: mineLines, base: baseLines, theirs: theirsLines, lines: mineLines }
  }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}

/**
 * Walks the base document, yielding `{ type: 'stable', lines }` for the
 * unchanged stretches and `{ type: 'region', region: resolveRegion(...) }`
 * for every region, in base order. Empty stable stretches are omitted.
 */
function mergeParts(mine, base, theirs) {
  const regions = buildRegions(mine, base, theirs)
  const parts = []
  let prevEnd = 0
  for (const region of regions) {
    if (region.baseStart > prevEnd) {
      parts.push({ type: 'stable', lines: base.slice(prevEnd, region.baseStart) })
    }
    parts.push({ type: 'region', region: resolveRegion(region, base) })
    prevEnd = region.baseEnd
  }
  if (prevEnd < base.length) {
    parts.push({ type: 'stable', lines: base.slice(prevEnd) })
  }
  return parts
}

export { mergeParts }
