const { spawnSync } = require("child_process")
function run(argv, mine, base, theirs) {
  const input = [mine, base, theirs].map(part => part.map(l => l + "\n").join("")).join("%%%\n")
  return spawnSync(process.execPath, ["src/cli.js", ...argv], { encoding: "utf8", input })
}

// multi-change region: mine changed twice, theirs changed once bridging them -> resolves to mine
let r = run(["merge"], ["a","X","c","Y","e"], ["a","b","c","d","e"], ["a","b","c","Z","e"])
console.log("test1", JSON.stringify(r.stdout), r.status)

// regions mode for a multi-change bridged region
r = run(["regions"], ["a","X","c","Y","e"], ["a","b","c","d","e"], ["a","b","c","Z","e"])
console.log("test2", JSON.stringify(r.stdout), r.status)

// no args
r = spawnSync(process.execPath, ["src/cli.js"], { encoding: "utf8", input: "" })
console.log("test3 noargs", r.status, JSON.stringify(r.stderr))

// too many args
r = spawnSync(process.execPath, ["src/cli.js", "merge", "extra"], { encoding: "utf8", input: "" })
console.log("test4 extra args", r.status, JSON.stringify(r.stderr))

// empty mine but non-empty base and theirs identical -> deletion
r = run(["merge"], [], ["a","b"], ["a","b"])
console.log("test5 all-deleted", JSON.stringify(r.stdout), r.status)

// insertion at very start
r = run(["merge"], ["Q","a"], ["a"], ["a"])
console.log("test6 insert-start", JSON.stringify(r.stdout), r.status)
'
","description":"Test additional edge cases"}

